  "translate_transcript.py": "import os
import requests

def translate_transcript(transcript):
    api_key = os.getenv('GOOGLE_CLOUD_API_KEY')
    url = 'https://translation.googleapis.com/language/translate/v2'
    params = {'key': api_key}
    data = {'q': transcript, 'target': 'es'}
    response = requests.post(url, params=params, data=data)
    response.raise_for_status()
    return response.json()['data']['translations'][0]['translatedText']",
  "moderate_transcript.py": "import os
import requests

def moderate_transcript(transcript):
    api_key = os.getenv('GOOGLE_CLOUD_API_KEY')
    url = 'https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze'
    params = {'key': api_key}
    data = {
        'comment': {'text': transcript},
        'requestedAttributes': {'TOXICITY': {}},
        'languages': ['en']
    }
    response = requests.post(url, params=params, json=data)
    response.raise_for_status()
    return response.json()['attributeScores']['TOXICITY']['summaryScore']['value'] < 0.5",
  "archive_summary.py": "import os
import requests

def archive_summary(transcript):
    api_key = os.getenv('GOOGLE_CLOUD_API_KEY')
    url = 'https://language.googleapis.com/v1/documents:analyzeEntities'
    params = {'key': api_key}
    data = {
        'document': {
            'type': 'PLAIN_TEXT',
            'content': transcript
        }
    }
    response = requests.post(url, params=params, json=data)
    response.raise_for_status()
    entities = response.json().get('entities', [])
    return ' '.join([entity['name'] for entity in entities[:5]])",
